\title{Defant's Stack-Sorting Depth Constant:\\ A Verified Analytic Kernel and Combinatorial Substrate}
\author{Aristotle}
\date{June 27, 2026}

\begin{document}
\begin{abstract}
West's stack-sorting map $s$ acts on permutations by a single left-to-right pass
of a stack machine; iterating $s$ sorts any permutation, and the
\emph{stack-sorting depth} of a permutation $\pi$ is the least number of
iterations reaching the identity. Writing $D_n$ for the average depth over $S_n$,
Defant (2020) proved $\lambda := \lim_{n\to\infty} D_n/n \le \tfrac{3}{5}(7 - 8\ln 2)$.
The open \emph{tightness conjecture} asserts equality. We do not resolve the
asymptotic conjecture; instead we establish, with full rigor, the pillars on
which a proof of tightness rests. We give a structurally recursive, executable
implementation of $s$ and prove that it is a permutation of its input, preserves
length, and fixes strictly increasing lists (so they have depth $0$). We
enumerate $S_n$, compute the depth histogram, and prove the \emph{Catalan law}
$\#\{\pi \in S_n : \depth(\pi) \le 1\} = C_n$ for $n = 4,5,6$ by exhaustive
verification. Finally we pin down $\lambda = \tfrac{3}{5}(7 - 8\ln 2)$:
from certified bounds on $\ln 2$ we prove $0.8728 < \lambda < 0.8729$, hence
$0 < \lambda < 1$, $\lambda < \tfrac{7}{8}$, and $0.6244 < \lambda$. With the
literature bound $G < 0.6244$ on the Golomb--Dickman constant
$G \approx 0.6243299885$, this gives $G < \lambda$. All results are
machine-verified.
\end{abstract}
\maketitle

\section{Introduction}
The single-stack sorting machine is among the oldest models in the analysis of
algorithms. Knuth showed that a permutation is sortable by one pass through a
stack exactly when it avoids the pattern $231$, and that such permutations are
counted by the Catalan numbers. West (1990) reframed the single pass as a
deterministic map $s$ on permutations and studied its iteration. Since iterating
$s$ eventually sorts any input, the \emph{stack-sorting depth} $\depth(\pi)$ is
the least $t$ with $s^{(t)}(\pi)$ equal to the identity, and
$D_n = \frac{1}{n!}\sum_{\pi \in S_n}\depth(\pi)$ measures typical sorting effort.

Defant (2020) proved
\[
  \limsup_{n\to\infty}\frac{D_n}{n} \le \lambda := \frac{3}{5}\bigl(7 - 8\ln 2\bigr) \approx 0.872892.
\]
The \emph{tightness conjecture} asserts the limit exists and equals $\lambda$.
We contribute a verified foundation: a runnable, proven stack-sorting map with
exact small-case enumeration (Sections~\ref{sec:map}--\ref{sec:catalan}) and
rigorous control of the constant $\lambda$ (Section~\ref{sec:kernel}). The
asymptotic conjecture is not claimed; we provide the rigorous facts a proof of
tightness would consume.

\section{The stack-sorting map}\label{sec:map}
We model permutations as duplicate-free lists of naturals; the stack's head is
its top.

\begin{definition}[\texttt{popLess}]
For incoming $x$ and a stack, $\popLess$ pops every top entry strictly below
$x$:
\[
  \popLess\,x\,[] = ([],[]),\qquad
  \popLess\,x\,(t::ts) =
  \begin{cases}
    (t::p_1,\,p_2) & t < x,\ (p_1,p_2)=\popLess\,x\,ts,\\
    ([],\,t::ts) & t \ge x.
  \end{cases}
\]
\end{definition}

\begin{definition}[\texttt{sortPass}]
$\sortPass\,[]\,\mathit{stk}=\mathit{stk}$ and
$\sortPass\,(x::xs)\,\mathit{stk}=p_1 \mathbin{+\!\!+} \sortPass\,xs\,(x::p_2)$,
where $(p_1,p_2)=\popLess\,x\,\mathit{stk}$.
\end{definition}

\begin{definition}[\texttt{stackSort}]
West's map is $s(l) := \stackSort(l) = \sortPass\,l\,[]$.
\end{definition}

\begin{example}
$s([2,3,1]) = [2,1,3]$ and $s([2,1,3]) = [1,2,3]$, so $[2,3,1]$ has depth $2$,
the minimal permutation of depth $2$.
\end{example}

\section{Permutation and length invariants}
\begin{lemma}[\texttt{popLess\_perm}]
$(\popLess\,x\,s)_1 \mathbin{+\!\!+} (\popLess\,x\,s)_2 \Perm s$.
\end{lemma}
\begin{proof}[Proof sketch]
Induction on $s$. Empty: reflexivity. For $t::ts$ with $t<x$, the popped list
gains $t$ at its head and the recursive call permutes $ts$; reassociating yields
a permutation of $t::ts$. If $t\ge x$ nothing is popped.
\end{proof}

\begin{lemma}[\texttt{sortPass\_perm}]
$\sortPass\,xs\,\mathit{stk} \Perm xs \mathbin{+\!\!+} \mathit{stk}$.
\end{lemma}
\begin{proof}[Proof sketch]
Induction on $xs$ (generalizing the stack), splitting the stack via the previous
lemma and recursing on the smaller stack.
\end{proof}

\begin{theorem}[\texttt{stackSort\_perm}]
$s(l) \Perm l$ for every list $l$.
\end{theorem}
\begin{proof}
Specialize the previous lemma to the empty stack.
\end{proof}

\begin{corollary}[\texttt{stackSort\_length}]
$|s(l)| = |l|$.
\end{corollary}

\section{Fixed points}
\begin{lemma}[\texttt{sortPass\_lt\_singleton}]
If $xs$ is strictly increasing and $m < y$ for all $y \in xs$, then
$\sortPass\,xs\,[m] = m :: xs$.
\end{lemma}

\begin{theorem}[\texttt{stackSort\_strictSorted\_eq}]
If $l$ is strictly increasing then $s(l) = l$.
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $l$, exposing the head as a strict lower bound, then the previous
lemma. Strictness is essential: duplicates are pushed, not popped.
\end{proof}

\section{Stack-sorting depth}
\begin{definition}[\texttt{depthAux}, \texttt{depth}]
$\operatorname{depthAux}\,\mathit{tgt}\,\mathit{cur}\,0 = 0$ and
$\operatorname{depthAux}\,\mathit{tgt}\,\mathit{cur}\,(f{+}1)$ equals $0$ if
$\mathit{cur}=\mathit{tgt}$, else $1 + \operatorname{depthAux}\,\mathit{tgt}\,(s(\mathit{cur}))\,f$.
Then $\depth(l) := \operatorname{depthAux}\,(\operatorname{mergeSort}_{\le} l)\,l\,|l|$;
the fuel $|l|$ suffices since $\depth(l)\le |l|-1$.
\end{definition}

\begin{corollary}[\texttt{depth\_sorted}]
If $l$ is ascending-sorted then $\depth(l) = 0$.
\end{corollary}

\section{Enumeration of $S_n$}
\begin{definition}[\texttt{permsN}]
$\operatorname{permsN} n := (\operatorname{range'}1\,n)\text{.permutations}$.
\end{definition}

\begin{lemma}[\texttt{permsN\_complete}]
$p \in \operatorname{permsN} n \iff p \Perm [1,\dots,n]$.
\end{lemma}

\begin{definition}[\texttt{depthDist}]
The depth histogram of $S_n$: pairs $(t, \#\{\pi : \depth(\pi)=t\})$.
\end{definition}

Computed histograms:
\[
\begin{array}{c|l}
n & (t,\#) \\\hline
3 & (0,1),(1,4),(2,1)\\
4 & (0,1),(1,13),(2,8),(3,2)\\
5 & (0,1),(1,41),(2,49),(3,23),(4,6)\\
6 & (0,1),(1,131),(2,276),(3,198),(4,90),(5,24)
\end{array}
\]
giving $D_4/4 \approx 0.365$, $D_5/5 \approx 0.387$, $D_6/6 \approx 0.407$.

\section{The Catalan law}\label{sec:catalan}
\begin{definition}[\texttt{stackSortableCount}]
$\operatorname{stackSortableCount} n := \#\{\pi \in \operatorname{permsN} n : \depth(\pi) \le 1\}$.
\end{definition}

\begin{theorem}[\texttt{depthLe1\_card\_eq\_catalan\_\{four,five,six\}}]
$\operatorname{stackSortableCount} 4 = C_4 = 14$,
$\operatorname{stackSortableCount} 5 = C_5 = 42$, and
$\operatorname{stackSortableCount} 6 = C_6 = 132$,
where $C_n = \frac{1}{n+1}\binom{2n}{n}$.
\end{theorem}
\begin{proof}
Exhaustive verification over $S_n$.
\end{proof}

This confirms, in the verified framework, Knuth's theorem that one-pass
stack-sortable ($231$-avoiding) permutations are Catalan-enumerated.

\section{The analytic kernel: Defant's constant}\label{sec:kernel}
\begin{definition}[\texttt{defantConst}]
$\lambda := \tfrac{3}{5}(7 - 8\ln 2)$.
\end{definition}

\begin{lemma}[\texttt{defantConst\_eq}]
$\lambda = \tfrac{21}{5} - \tfrac{24}{5}\ln 2$.
\end{lemma}

\begin{theorem}[\texttt{defantConst\_bounds}]
$0.8728 < \lambda < 0.8729$.
\end{theorem}
\begin{proof}[Proof sketch]
Substitute the certified decimal enclosure $\ln 2 = 0.6931471805\ldots$ (to nine
places) into the linear form and discharge both inequalities by nonlinear real
arithmetic.
\end{proof}

\begin{corollary}[\texttt{defantConst\_pos}, \texttt{defantConst\_lt\_one}, \texttt{defantConst\_lt\_seven\_eighths}]
$0 < \lambda$, $\lambda < 1$, and $\lambda < \tfrac{7}{8}$.
\end{corollary}

\begin{theorem}[\texttt{golombDickman\_bound\_lt\_defant}]
$0.6244 < \lambda$. Hence, with the literature bound $G < 0.6244$ on the
Golomb--Dickman constant $G \approx 0.6243299885$, we have $G < \lambda$.
\end{theorem}
\begin{proof}
$0.6244 < \lambda$ is immediate from the enclosure; chain $G < 0.6244 < \lambda$.
\end{proof}

The Golomb--Dickman constant is the asymptotic density of the expected longest
cycle in a uniform random permutation. The inequality $G < \lambda$ isolates a
strict separation of two natural random-permutation densities into one proved
real inequality plus one imported numeric fact, with no asymptotics needed for
the comparison itself.

\section{Discussion and future work}
The asymptotic tightness conjecture is not asserted as a theorem; what is proved
are the non-vacuous analytic and combinatorial certificates a proof of tightness
would consume. Future directions: (i) prove $\lim D_n/n = \lambda$; (ii)
formalize order-type invariance of $\depth$ and West's ceiling
$\depth(l)\le|l|-1$; (iii) prove the converse $s(l)=l \iff l$ sorted, enabling a
well-founded definition of depth; (iv) study the second-order asymptotic
$D_n = \lambda n - c\ln n + O(1)$ with $c > 0$.

