\bibitem{defant} C.~Defant, work on expected stack-sorting depth and the upper
bound $\tfrac{3}{5}(7 - 8\ln 2)$, 2020.
\bibitem{gd} The Golomb--Dickman constant $G \approx 0.6243299885$.
\end{thebibliography}

