"""Catalan law demonstration: one-pass stack-sortable permutations are
counted by the Catalan numbers, verified by exhaustive enumeration of S_n."""
from __future__ import annotations
from itertools import permutations
from math import comb
from typing import List, Tuple


def pop_less(x: int, stack: List[int]) -> Tuple[List[int], List[int]]:
    i = 0
    while i < len(stack) and stack[i] < x:
        i += 1
    return stack[:i], stack[i:]


def stack_sort(seq: List[int]) -> List[int]:
    stack: List[int] = []
    out: List[int] = []
    for x in seq:
        popped, rest = pop_less(x, stack)
        out.extend(popped)
        stack = [x] + rest
    out.extend(stack)
    return out


def depth(seq: List[int]) -> int:
    target, cur, c = sorted(seq), list(seq), 0
    for _ in range(len(seq) + 1):
        if cur == target:
            return c
        cur, c = stack_sort(cur), c + 1
    return c


def catalan(n: int) -> int:
    return comb(2 * n, n) // (n + 1)


def one_pass_count(n: int) -> int:
    return sum(1 for p in permutations(range(1, n + 1)) if depth(list(p)) <= 1)


if __name__ == "__main__":
    for n in range(1, 8):
        c, cat = one_pass_count(n), catalan(n)
        print(f"n={n}: one-pass={c}, C_n={cat}, match={c == cat}")

