function STACK_SORT(seq):
    stack <- empty;  out <- empty
    for x in seq:
        (popped, rest) <- POP_LESS(x, stack)
        append popped to out
        stack <- [x] ++ rest          # push x on top
    append stack to out               # flush
    return out

function POP_LESS(x, stack):
    i <- 0
    while i < |stack| and stack[i] < x:
        i <- i + 1
    return (stack[0:i], stack[i:])
